package org.eclipse.rdf4j.sail.nativerdf.wal;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.nativerdf.ValueStore;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreWalBootstrapDescriptionTest {

	@TempDir
	Path directory;

	@Test
	void bootstrapMatchesOrdinaryMintsForAllKindsAndLiteralDirections() throws Exception {
		var factory = SimpleValueFactory.getInstance();
		IRI subject = factory.createIRI("urn:bootstrap:subject");
		IRI predicate = factory.createIRI("urn:bootstrap:predicate");
		TripleTerm triple = factory.createTripleTerm(subject, predicate, factory.createLiteral("triple object"));
		List<Value> values = List.of(subject, predicate, factory.createIRI("urn:unicode:é-😀"),
				factory.createBNode("bootstrap-node"), factory.createLiteral("plain text"),
				factory.createLiteral("custom", factory.createIRI("urn:bootstrap:datatype")),
				factory.createLiteral("language", "EN"),
				factory.createLiteral("left", "en", Literal.BaseDirection.LTR),
				factory.createLiteral("right", "ar", Literal.BaseDirection.RTL),
				factory.createLiteral("é-😀".repeat(2000)), triple,
				factory.createTripleTerm(subject, predicate, triple));
		Path original = Files.createDirectories(directory.resolve("original"));
		Path legacy = Files.createDirectories(directory.resolve("legacy"));
		ValueStoreWalConfig originalConfig = config(directory.resolve("original-wal"));
		ValueStoreWalConfig bootstrapConfig = config(directory.resolve("bootstrap-wal"));
		try (ValueStoreWAL wal = ValueStoreWAL.open(originalConfig);
				ValueStore minted = new ValueStore(original.toFile(), false, 16, 16, 16, 16, wal);
				ValueStore withoutWal = new ValueStore(legacy.toFile())) {
			for (Value value : values) {
				assertThat(withoutWal.storeValue(value)).isEqualTo(minted.storeValue(value));
			}
			minted.sync();
			withoutWal.sync();
		}
		try (ValueStoreWAL wal = ValueStoreWAL.open(bootstrapConfig);
				ValueStore rebuilt = new ValueStore(legacy.toFile(), false, 16, 16, 16, 16, wal)) {
			rebuilt.sync();
		}
		assertThat(descriptions(bootstrapConfig)).containsExactlyElementsOf(descriptions(originalConfig));
	}

	private ValueStoreWalConfig config(Path walDirectory) {
		return ValueStoreWalConfig.builder()
				.walDirectory(walDirectory)
				.storeUuid("bootstrap-descriptions")
				.syncBootstrapOnOpen(true)
				.build();
	}

	private List<List<Object>> descriptions(ValueStoreWalConfig config) throws Exception {
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config)) {
			return reader.scan()
					.records()
					.stream()
					.map(record -> List.<Object>of(record.id(), record.valueKind(),
							record.lexical(), record.datatype(), record.language(), record.hash()))
					.toList();
		}
	}
}
